const std = @import("std");

pub fn main() !void {
    var prng = std.rand.DefaultPrng.init(42);
    const rand = prng.random();
    var arr = [_]i32{ 1, 2, 3, 4, 5, 6, 7 };

    var i: usize = arr.len;
    while (i > 0) {
        i -= 1;
        const j = rand.intRangeLessThan(usize, 0, i + 1);
        const temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    for (arr) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}
